/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Group names accepted wherever a status filter is read (ADR 0009). */
export type IssueStatusGroup = "open" | "closed";

/** A status as written in a filter: a concrete status or a group name. */
export type IssueStatusToken = IssueStatus | IssueStatusGroup;

/** `open` is every status that is not closed; `closed` is the closed set. */
export const ISSUE_STATUS_GROUPS: Readonly<Record<IssueStatusGroup, readonly IssueStatus[]>> = {
  open: ISSUE_STATUSES.filter((status) => !CLOSED_ISSUE_STATUSES.includes(status)),
  closed: CLOSED_ISSUE_STATUSES,
};

export function isIssueStatusGroup(value: string): value is IssueStatusGroup {
  return Object.prototype.hasOwnProperty.call(ISSUE_STATUS_GROUPS, value);
}

/**
 * Expands status tokens to concrete statuses, keeping first-seen order and
 * dropping duplicates and unknown tokens.
 */
export function expandIssueStatuses(tokens: readonly string[]): IssueStatus[] {
  const expanded: IssueStatus[] = [];
  for (const token of tokens) {
    const members: readonly IssueStatus[] = isIssueStatusGroup(token)
      ? ISSUE_STATUS_GROUPS[token]
      : ISSUE_STATUSES.includes(token as IssueStatus)
        ? [token as IssueStatus]
        : [];
    for (const status of members) {
      if (!expanded.includes(status)) expanded.push(status);
    }
  }
  return expanded;
}

/** The filter value that means "the signed-in user". Resolved by the service. */
export const ME_TOKEN = "me" as const;
export type MeToken = typeof ME_TOKEN;

