import type { CalendarDay, IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

/** True for a real calendar date written `YYYY-MM-DD` (rejects e.g. Feb 31). */
export function isCalendarDay(value: string): value is CalendarDay {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const start = Date.parse(`${value}T00:00:00.000Z`);
  return !Number.isNaN(start) && new Date(start).toISOString().startsWith(value);
}

/**
 * The exclusive upper bound a `due_before` value stands for. A calendar day
 * includes the whole day, so its bound is the start of the next UTC day; a
 * full timestamp is its own bound. Normalised to the stored ISO form so a
 * text comparison against `due_at` is correct.
 */
export function dueBeforeBound(value: IsoTimestamp | CalendarDay): IsoTimestamp {
  if (!isCalendarDay(value)) return toIsoTimestamp(value);
  return toIsoTimestamp(new Date(Date.parse(`${value}T00:00:00.000Z`) + DAY_MS));
}

