/** A status filter token: a concrete status, or the `open` / `closed` group. */
export const issueStatusFilterSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
  "open",
  "closed",
]);

/** `me` stands for the signed-in user; the service resolves it. */
const userFilterSchema = z.union([userIdSchema, z.literal(ME_TOKEN)]);

/**
 * `due_before`: a calendar day (`YYYY-MM-DD`, whole day included) or a full
 * ISO-8601 timestamp (strictly before). Timestamps are normalised to the
 * stored UTC form.
 */
export const dueBeforeSchema = z.union([
  z
    .string()
    .refine(isCalendarDay, "must be a YYYY-MM-DD calendar date")
    .transform((value) => value as CalendarDay),
  z.iso
    .datetime({ offset: true })
    .transform((value) => toIsoTimestamp(value)),
]);

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: z.array(issueStatusFilterSchema).optional(),
    priority: z.array(issuePrioritySchema).optional(),
    assigneeId: userFilterSchema.nullable().optional(),
    authorId: userFilterSchema.optional(),
    labelIds: z.array(labelIdSchema).optional(),
    query: z.string().max(200).optional(),
    dueBefore: dueBeforeSchema.optional(),
    /** `only` in the URL: archived issues and nothing else. */
    onlyArchived: z.boolean().optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape);

/**
 * The filter after `me` has been resolved: what the repository receives. The
 * repository expands status groups itself, so both spellings land the same.
 */
export type ResolvedIssueFilterInput = Omit<
  IssueFilterInput,
  "assigneeId" | "authorId" | "status"
> & {
  assigneeId?: UserId | null;
  authorId?: UserId;
  status?: readonly IssueStatusToken[];
};

