 * (all-of), so each label narrows the list rather than widening it.
 */
function labelPredicates(
  orgId: OrgId,
  labelIds: readonly LabelId[] | undefined,
): readonly SQL[] {
  return (labelIds ?? []).map((labelId) =>
    inArray(
      issues.id,
      getDb()
        .select({ id: issueLabels.issueId })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, labelId),
          ),
        ),
    ),
  );
}

